 ***************/
.background {
  color: #F7F7F7;
  background-color: #2c2c2c; }
  .background:backdrop {
    text-shadow: none;
    -gtk-icon-shadow: none; }

dnd {
  color: #F7F7F7; }

.normal-icons {
  -gtk-icon-size: 16px; }

.large-icons {
  -gtk-icon-size: 32px; }

image:disabled {
  -gtk-icon-filter: opacity(0.5); }

picture:disabled {
  opacity: 0.5; }

.view, iconview,
textview > text {
  color: white;
  background-color: #272727; }
  .view:disabled, iconview:disabled,
  textview > text:disabled {
    color: #929292;
    background-color: #2a2a2a; }
  .view:selected:focus, iconview:selected:focus, .view:selected, iconview:selected,
  textview > text:selected:focus,
  textview > text:selected {
    border-radius: 3px; }

textview > text {
  background-color: transparent; }
  textview > text > selection {
    background-color: rgba(158, 158, 158, 0.5); }
    textview > text > selection:focus-within {
      background-color: rgba(119, 100, 216, 0.8); }

textview:drop(active) {
  caret-color: #109b26; }

textview > border {
  background-color: #2a2a2a; }

iconview {
  transition-property: outline, outline-width, outline-offset, outline-color;
  transition-duration: 300ms;
  animation-timing-function: ease-in-out; }
  iconview {
    outline: 0 solid transparent;
    outline-offset: 4px; }
  iconview:focus:focus-visible {
    outline-color: rgba(169, 157, 230, 0.7);
